package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import com.insight.quantlife.*;
/** Synthetic emulator only: signed cover install, real SQLite/WebView, mocked model. */
public class WorkLogSplitTest extends WorkClockTest {
 final String id="split-legacy-shift",note="原始工作内容\n完成报告和测试，下一步沟通。";
 JSONObject fixture()throws Exception{return new JSONObject().put("id",id).put("type","work").put("date","2025-08-01").put("title","合成工作").put("workStart","2025-08-01T09:00:00").put("workEnd","2025-08-01T18:00:00").put("breaks",new JSONArray()).put("durationMinutes",540).put("note",note).put("tags",new JSONArray().put("合成项目"));}
 void seed()throws Exception{holdAutomation();check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.7.4"),"Baseline 1.7.4");h.call("saveRecord",new JSONObject().put("record",fixture()).put("allowDuplicate",true));JSONObject snap=init();try(TrackStore t=new TrackStore(getTargetContext())){snap.put("raw",t.diagnostics("2026-12-15").getJSONArray("rawPoints")).put("gpx",t.gpx("2026-12-15"));}try(FileOutputStream f=getTargetContext().openFileOutput("work-log-split-baseline.json",0)){f.write(snap.toString().getBytes("UTF-8"));}}
 JSONObject baseline()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getTargetContext().openFileInput("work-log-split-baseline.json")){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}
 int linked(String rid)throws Exception{JSONArray a=init().getJSONArray("records");int n=0;for(int i=0;i<a.length();i++)if(a.getJSONObject(i).optString("sourceShiftId").equals(rid))n++;return n;}
 void flow()throws Exception{
  holdAutomation();if(!phase.equals("retry")){JSONObject old=baseline(),cur=init();check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.7.5"),"Signed cover install 1.7.5");
  for(String k:new String[]{"messages","wikiPages","chatSession"})check(old.get(k).toString().equals(cur.get(k).toString()),"Upgrade preserves "+k);
  JSONObject a=old.getJSONObject("settings"),b=cur.getJSONObject("settings");a.remove("wikiAutomation");b.remove("wikiAutomation");check(a.toString().equals(b.toString()),"All model/search settings unchanged");try(TrackStore t=new TrackStore(getTargetContext())){check(old.getString("gpx").equals(t.gpx("2026-12-15"))&&old.getJSONArray("raw").toString().equals(t.diagnostics("2026-12-15").getJSONArray("rawPoints").toString()),"GPS unchanged");}
  JSONArray rs=old.getJSONArray("records");for(int i=0;i<rs.length();i++){JSONObject r=rs.getJSONObject(i),current=find(r.getString("id"));if(r.optString("type").equals("work")&&!r.optString("note").trim().isEmpty()){check(current.getString("note").isEmpty(),"Shift cleared after migration");boolean found=false;JSONArray all=init().getJSONArray("records");for(int j=0;j<all.length();j++){JSONObject log=all.getJSONObject(j);if(log.optString("sourceShiftId").equals(r.getString("id"))){found=log.getString("note").equals(r.getString("note"))&&log.getString("date").equals(r.getString("date"))&&log.getInt("durationMinutes")==0;}}check(found,"Exact legacy content/date preserved in non-timed log");r.put("note","");r.remove("updatedAt");current.remove("updatedAt");check(r.toString().equals(current.toString()),"Shift clock/provenance unchanged");}else check(r.toString().equals(current.toString()),"Unrelated record unchanged");}
  check(linked(id)==1,"One linked migrated log");reload();holdAutomation();check(linked(id)==1,"Reopening is idempotent");h.call("saveRecord",new JSONObject().put("record",fixture()).put("allowDuplicate",true));check(linked(id)==1&&find(id).getString("note").isEmpty(),"Replaying old shift note does not duplicate log");}
  h.call("saveRecord",new JSONObject().put("record",fixture().put("note","")).put("allowDuplicate",true));h.call("newChat",new JSONObject());reload();holdAutomation();click("[data-page=chat]");sendText("2025-08-01工作了多久");click(".chat-message:last-child [data-record='"+id+"']");jsCheck("!document.querySelector('#editor').innerText.includes('我的笔记')","Shift detail contains time only");click("#edit-record");jsCheck("!document.querySelector('#record-note')&&document.querySelector('#work-start')!==null","Shift editor has no notes textarea");click("#close-editor");
  JSONArray prior=init().getJSONArray("records");for(int j=0;j<prior.length();j++){JSONObject r=prior.getJSONObject(j);if(r.optString("type").equals("work_note")&&(r.optString("note").equals("今天的工作：完成访谈")||r.optString("note").equals("今天的工作：完成报告")))h.call("deleteRecord",new JSONObject().put("id",r.getString("id")));}h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",model("SYNTHETIC-ONLY"))));h.call("newChat",new JSONObject());reload();holdAutomation();chatMock();click("[data-page=chat]");
  sendText("今天的工作：完成访谈");click("[data-save-candidate]");until("!document.querySelector('[data-save-candidate]')");sendText("今天的工作：完成报告");click("[data-save-candidate]");until("!document.querySelector('[data-save-candidate]')");jsCheck("!document.querySelector('#confirm-dialog').open","Different same-day logs require no false duplicate override");JSONArray all=init().getJSONArray("records");int logs=0;for(int i=0;i<all.length();i++){JSONObject r=all.getJSONObject(i);if(r.optString("type").equals("work_note")&&(r.optString("note").equals("今天的工作：完成访谈")||r.optString("note").equals("今天的工作：完成报告")))logs++;}check(logs==2,"Two chat-confirmed independent work logs saved");
  h.js("window.__baseCall=LifeNative.call;LifeNative.call=function(action,payload,rid){if(action!=='ask'){__baseCall(action,payload,rid);return;}const p=JSON.parse(payload);const out=p.tool.name==='plan_record_search'?{intent:'update',topic:'',keywords:[],dateStart:'',dateEnd:''}:{answer:'待确认',records:[],citations:[],actions:[{kind:'create_work_note',date:'2025-08-01',title:'同日工作日志',note:'AI工具新增进展'}]};setTimeout(()=>nativeReply({id:rid,data:{text:JSON.stringify(out),model:'synthetic-log-tool'}}),15)}");sendText("再记一份工作进展");jsCheck("document.querySelectorAll('[data-confirm-change]').length===1","Native work-log tool yields separate confirmation");int before=init().getJSONArray("records").length();click("[data-confirm-change]");until("!document.querySelector('[data-confirm-change]')");check(init().getJSONArray("records").length()==before+1,"Confirmed native tool creates independent log");check(find(id).getString("note").isEmpty()&&find(id).getInt("durationMinutes")==540,"Log tool leaves shift and hours unchanged");
  click("[data-action=chat-history]");click("#drawer-model");jsCheck("!document.querySelector('.model-policy')&&!document.querySelector('#main').innerText.includes('轨迹不发送')","Model page simplified");click("[data-go=chat]");click("[data-action=chat-tools]");jsCheck("document.querySelector('.chat-privacy')&&!document.querySelector('.chat-privacy').open","Privacy/billing retained only in collapsed detail");click("#close-editor");h.screenshot("work-log-split-1.7.5.png");
 }
 @Override public void onStart(){Bundle r=new Bundle();try{h=new MainHost(this);h.open();if(phase.equals("seed"))seed();else flow();r.putString("stream","PASS "+passed+" work-log split/upgrade/UI checks; phase="+phase+"\n");finish(Activity.RESULT_OK,r);}catch(Throwable e){r.putString("stream","FAIL after "+passed+": "+e+"\n");finish(Activity.RESULT_CANCELED,r);}}
}
